/* map_dto.c: both directions live here, nowhere else */
int user_from_dto(const struct user_dto *dto, struct user *out) {
    size_t n = strlen(dto->full_name) + 1;
    out->name = malloc(n);                  /* ownership: caller frees */
    if (!out->name) return -ENOMEM;
    memcpy(out->name, dto->full_name, n);
    out->id = (uint64_t)dto->id;            /* signed -> unsigned: checked */
    out->admin = dto->is_admin != 0;        /* absent keys are errors */
    return 0;
}
int user_to_dto(const struct user *u, struct user_dto *out);
